package com.photospace.storage;

import java.net.URI;
import java.nio.file.Path;
import java.time.Duration;
import java.time.Instant;
import java.util.Map;
import java.util.Optional;

/**
 * Private object storage for photos. Objects are never public: browsers reach them only through short-lived
 * presigned URLs that this interface issues for one key and one method. Keys are always generated by the
 * server. Failures surface as {@link StorageException}, so no provider SDK type leaves the adapter.
 */
public interface ObjectStorage {

    /**
     * A URL the browser can {@code PUT} exactly {@code contentLength} bytes of {@code contentType} to, until it
     * expires. The returned headers must be sent with the request.
     */
    PresignedUpload presignUpload(String key, String contentType, long contentLength, Duration validFor);

    /** A URL that lets the holder {@code GET} one object until it expires. */
    URI presignDownload(String key, Duration validFor);

    /**
     * A URL that lets the holder {@code GET} one object as a file download until it expires. The browser saves it
     * as {@code filename} and is told its type is {@code contentType}; both are part of the signature.
     */
    URI presignAttachment(String key, String filename, String contentType, Duration validFor);

    /** The object's size in bytes, or empty if there is no such object. */
    Optional<Long> size(String key);

    /** Writes the object to {@code target}, replacing that file. */
    void download(String key, Path target);

    /** Stores {@code content} under {@code key}, replacing any object already there. */
    void upload(String key, byte[] content, String contentType);

    /** Deletes the object. Deleting a missing object succeeds, so retries are harmless. */
    void delete(String key);

    /** A presigned upload. The URL is a credential for that object: never log or persist it. */
    record PresignedUpload(URI url, Map<String, String> headers, Instant expiresAt) {}
}
